const input = $input.first()?.json ?? {};
const document = input.document ?? input;
const chunks = Array.isArray(document.chunks) ? document.chunks : [];
const required = ['source_key', 'title', 'source_type', 'checksum'];
for (const field of required) {
  if (typeof document[field] !== 'string' || !document[field].trim()) {
    throw new Error(`document.${field} is required`);
  }
}
if (chunks.length === 0) throw new Error('document.chunks must contain at least one parsed chunk');
const normalizedChunks = chunks.map((chunk, index) => {
  if (!chunk || typeof chunk.content !== 'string' || !chunk.content.trim()) {
    throw new Error(`document.chunks[${index}].content is required`);
  }
  const ordinal = Number.isInteger(chunk.ordinal) ? chunk.ordinal : index;
  if (ordinal < 0) throw new Error(`document.chunks[${index}].ordinal must be >= 0`);
  if (chunk.embedding !== undefined && chunk.embedding !== null && (!Array.isArray(chunk.embedding) || chunk.embedding.length !== 768)) {
    throw new Error(`document.chunks[${index}].embedding must contain 768 values when provided`);
  }
  return {
    chunk_key: chunk.chunk_key || null,
    content: chunk.content.trim(),
    search_terms: String(chunk.search_terms ?? `${chunk.section ?? ''} ${chunk.content}`).trim(),
    page_start: chunk.page_start ?? null,
    page_end: chunk.page_end ?? null,
    section: String(chunk.section ?? ''),
    ordinal,
    decision_steps: Array.isArray(chunk.decision_steps) ? chunk.decision_steps : [],
    project_types: Array.isArray(chunk.project_types) ? chunk.project_types : [],
    geography: Array.isArray(chunk.geography) ? chunk.geography : [],
    embedding: chunk.embedding ?? null,
    metadata: chunk.metadata && typeof chunk.metadata === 'object' ? chunk.metadata : {},
  };
});
return [{ json: { document: {
  source_key: document.source_key.trim(),
  title: document.title.trim(),
  source_type: document.source_type.trim(),
  source_url: String(document.source_url ?? ''),
  object_key: String(document.object_key ?? ''),
  version: Number.isInteger(document.version) && document.version > 0 ? document.version : 1,
  checksum: document.checksum.trim(),
  tenant_id: String(document.tenant_id ?? 'default'),
  visibility: document.visibility === 'public' ? 'public' : 'restricted',
  access_groups: Array.isArray(document.access_groups) ? document.access_groups : [],
  metadata: document.metadata && typeof document.metadata === 'object' ? document.metadata : {},
  chunks: normalizedChunks,
} } }];

const source = $('Validate Parsed Source').first().json.document;
const result = $input.first()?.json ?? {};
const embeddings = Array.isArray(result.embeddings) ? result.embeddings : [];
if (embeddings.length !== source.chunks.length) throw new Error('chunk embedding count does not match parsed chunks');
return [{ json: { document: {
  ...source,
  metadata: { ...source.metadata, embedding_model: result.model, embedding_dimensions: result.dimensions },
  chunks: source.chunks.map((chunk, index) => ({ ...chunk, embedding: embeddings[index] })),
} } }];

const row = $input.first()?.json ?? {};
return [{ json: {
  published: true,
  document_id: row.document_id,
  source_key: row.source_key,
  version: row.version,
  status: row.status,
  chunk_count: Number(row.chunk_count ?? 0),
} }];
